import { type FormEvent, type ReactNode, useEffect, useState } from 'react';
import { QueryClient, QueryClientProvider, useQueryClient } from '@tanstack/react-query';
import {
  Activity, ArrowUpRight, BarChart3, Bell, BookOpen, BriefcaseBusiness,
  CheckCircle2, CircleDollarSign, ClipboardList, Clock3, CreditCard,
  FileText, GraduationCap, LayoutDashboard, Menu, Moon, Pencil, Plus, Search, Settings2,
  Sun, Trash2, UsersRound, WalletCards, X
} from 'lucide-react';
import {
  getGetActivityQueryKey, getGetDashboardSummaryQueryKey,
  getListEmployeesQueryKey,
  getListInvoicesQueryKey, getListStudentsQueryKey, useCreateEmployee, useCreateJournalEntry,
  useCreateStudent, useGetActivity, useGetDashboardSummary, useGetStudent, useListEmployees,
  useListInvoices, useListStudents, useRecordPayment, useUpdateStudent, useDeleteStudent, useDeleteEmployee,
  getListInquiriesQueryKey, useCreateInquiry, useDeleteInquiry, useEnrollInquiry,
  useGenerateInquiryInvoice, useGetAdmissionsContext, useGetInquiry, useListInquiries, useUpdateInquiryFees,
  type AdmissionsContext, type Inquiry, setBaseUrl
} from '@workspace/api-client-react';
import { Link, Route, Switch, useLocation, Router as WouterRouter } from 'wouter';
import { ErrorBoundary } from '@/components/error-boundary';
import { Toaster } from '@/components/ui/toaster';
import { TooltipProvider } from '@/components/ui/tooltip';
import NotFound from '@/pages/not-found';
import './index.css';

const API_BASE = import.meta.env.VITE_API_URL || '';
if (API_BASE) setBaseUrl(API_BASE);

const queryClient = new QueryClient();

const refreshWorkspace = (qc: QueryClient, keys: readonly (readonly unknown[])[]) => {
  keys.forEach((queryKey) => {
    void qc.invalidateQueries({ queryKey });
  });
};

const formatCurrency = (value: number | undefined) =>
  value === undefined ? 'Rs. 0' : `Rs. ${Number(value).toLocaleString()}`;
const initials = (name = '') => name.split(' ').map((part) => part[0]).slice(0, 2).join('').toUpperCase() || 'NA';
const titleCase = (value = '') => value.replace(/[-_]/g, ' ').replace(/\b\w/g, (letter) => letter.toUpperCase());
const setupRequest = async (path: string, init?: RequestInit) => {
  const response = await fetch(`${API_BASE}/api${path}`, { ...init, headers: { 'content-type': 'application/json', ...(init?.headers ?? {}) } });
  const body = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(body.error || 'Request failed');
  return body;
};

function EmptyState({ icon: Icon = ClipboardList, title, body, action }: { icon?: typeof ClipboardList; title: string; body: string; action?: ReactNode }) {
  return <div className="empty" data-testid={`empty-${title.toLowerCase().replaceAll(' ', '-')}`}><div className="empty-icon"><Icon size={18} /></div><h3>{title}</h3><p>{body}</p>{action ? <div style={{ marginTop: 16 }}>{action}</div> : null}</div>;
}

function ErrorState({ onRetry }: { onRetry?: () => void }) {
  return <div className="error-box" data-testid="status-error"><span>We couldn't load this view. Your records are safe; try again when ready.</span>{onRetry ? <button className="btn btn-danger" onClick={onRetry} data-testid="button-retry">Retry</button> : null}</div>;
}

function LoadingCards() {
  return <div className="grid metric-grid" data-testid="status-loading"><div className="skeleton skeleton-card" /><div className="skeleton skeleton-card" /><div className="skeleton skeleton-card" /><div className="skeleton skeleton-card" /></div>;
}


function Layout({ children }: { children: ReactNode }) {
  const [location] = useLocation();
  const [menuOpen, setMenuOpen] = useState(false);
  const [schoolName, setSchoolName] = useState('School name');
  const [academicYear, setAcademicYear] = useState('');
  const [theme, setTheme] = useState<'light' | 'dark'>(() => { try { return (localStorage.getItem('theme') as 'light' | 'dark') || 'light'; } catch { return 'light'; } });
  useEffect(() => { document.documentElement.setAttribute('data-theme', theme); try { localStorage.setItem('theme', theme); } catch {} }, [theme]);
  useEffect(() => { setupRequest('/setup').then((d: { school: { name: string; academicYear: string } }) => { setSchoolName(d.school.name); setAcademicYear(d.school.academicYear); }).catch(() => {}); }, [location]);
  const [openDropdown, setOpenDropdown] = useState<'none' | 'notifications' | 'profile'>('none');
  useEffect(() => { const handler = () => setOpenDropdown('none'); if (openDropdown !== 'none') { document.addEventListener('click', handler); return () => document.removeEventListener('click', handler); } }, [openDropdown]);
  const current = location === '/' ? 'Overview' : location.slice(1) === 'hr' ? 'People operations' : location.slice(1) === 'grades' ? 'Grades & Sections' : titleCase(location.slice(1));
  const initials = schoolName.split(' ').filter(Boolean).slice(0, 2).map((w) => w[0]).join('').toUpperCase();
  const navItems = [
    { href: '/', label: 'Overview', icon: LayoutDashboard },
    { href: '/admissions', label: 'Admissions', icon: ClipboardList },
    { href: '/students', label: 'Students', icon: GraduationCap },
    { href: '/grades', label: 'Grades', icon: BookOpen },
    { href: '/hr', label: 'People operations', icon: UsersRound },
    { href: '/finance', label: 'Finance', icon: WalletCards },
    { href: '/settings', label: 'School setup', icon: Settings2 },
  ];
  return <div className="app-shell">
    <aside className={`sidebar ${menuOpen ? 'open' : ''}`} data-testid="sidebar">
      <div className="brand"><div className="brand-mark">{initials}</div><div><div className="brand-name">{schoolName}</div><span className="brand-kicker">school operations</span></div></div>
      <div className="nav-label">Workspace</div>
      <nav className="nav-stack" aria-label="Main navigation">
        {navItems.map(({ href, label, icon: Icon }) => <Link href={href} key={href} className={`nav-link ${location === href ? 'active' : ''}`} onClick={() => setMenuOpen(false)} data-testid={`link-${label.toLowerCase().replaceAll(' ', '-')}`}><Icon /><span>{label}</span></Link>)}
      </nav>
      <div className="sidebar-bottom"><div className="school-switch"><div className="school-avatar">{initials}</div><div><div className="school-name">{schoolName}</div>{academicYear ? <div className="school-meta">Academic year {academicYear}</div> : null}</div></div></div>
    </aside>
    <main className="main">
      <header className="topbar"><div className="breadcrumb"><span>DAYMARK /</span><strong data-testid="text-current-page">{current}</strong></div><div className="top-actions" style={{ position: 'relative' }}><button className="icon-button mobile-menu" onClick={() => setMenuOpen((open) => !open)} aria-label="Open navigation" data-testid="button-open-navigation"><Menu size={17} /></button><div style={{ position: 'relative' }}><button className="icon-button" aria-label="Notifications" data-testid="button-notifications" onClick={(e) => { e.stopPropagation(); setOpenDropdown((d) => d === 'notifications' ? 'none' : 'notifications'); }} style={{ position: 'relative' }}><Bell size={16} /><span style={{ position: 'absolute', top: 5, right: 5, width: 7, height: 7, borderRadius: '50%', background: 'var(--rose)', border: '1.5px solid var(--surface-2)' }} /></button>{openDropdown === 'notifications' ? <div className="topbar-dropdown" onClick={(e) => e.stopPropagation()}><div className="topbar-dropdown-head">Notifications</div><div className="topbar-dropdown-empty">No new notifications</div></div> : null}</div><Link href="/settings" className="icon-button" aria-label="Settings" data-testid="button-settings"><Settings2 size={16} /></Link><button className="theme-toggle" onClick={() => setTheme((t) => t === 'light' ? 'dark' : 'light')} aria-label="Toggle theme" data-testid="button-theme-toggle">{theme === 'light' ? <Moon size={16} /> : <Sun size={16} />}</button><div style={{ position: 'relative' }}><button className="avatar" data-testid="text-user-avatar" onClick={(e) => { e.stopPropagation(); setOpenDropdown((d) => d === 'profile' ? 'none' : 'profile'); }}>{initials}</button>{openDropdown === 'profile' ? <div className="topbar-dropdown" onClick={(e) => e.stopPropagation()} style={{ minWidth: 180 }}><div className="topbar-dropdown-head" style={{ paddingBottom: 8 }}>{schoolName}</div><div style={{ fontSize: 11, color: 'var(--text-3)', paddingBottom: 10, borderBottom: '1px solid var(--border-2)' }}>{academicYear || 'School administrator'}</div><Link href="/settings" className="topbar-dropdown-item" onClick={() => setOpenDropdown('none')}><Settings2 size={14} /> School setup</Link><button className="topbar-dropdown-item" onClick={() => { setTheme((t) => t === 'light' ? 'dark' : 'light'); setOpenDropdown('none'); }}>{theme === 'light' ? <Moon size={14} /> : <Sun size={14} />} {theme === 'light' ? 'Dark mode' : 'Light mode'}</button></div> : null}</div></div></header>
      {children}
    </main>
  </div>;
}

function PageHead({ eyebrow, title, subtitle, action }: { eyebrow: string; title: string; subtitle: string; action?: ReactNode }) {
  return <div className="page-head"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p className="page-subtitle">{subtitle}</p></div>{action}</div>;
}

function Dashboard() {
  const schoolName = JSON.parse(localStorage.getItem('erp-prefs') || '{}').schoolName || 'School';
  const summaryQuery = useGetDashboardSummary();
  const activityQuery = useGetActivity();
  const summary = summaryQuery.data;
  const activity = activityQuery.data ?? [];
  const trend = summary?.enrollmentTrend ?? [];
  const maxTrend = Math.max(...trend.map((point) => point.value), 1);
  const attendance = summary?.attendanceRate;
  return <div className="content">
    <PageHead eyebrow={new Date().toLocaleDateString('en-US', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })} title={`Good morning, ${schoolName}.`} subtitle="Here’s the operating picture for Alder Finch Academy." />
    {summaryQuery.isLoading ? <LoadingCards /> : summaryQuery.isError ? <ErrorState onRetry={() => summaryQuery.refetch()} /> : <div className="grid metric-grid">
      {[['Enrolled students', summary ? String(summary.students) : '—', 'Current roster', GraduationCap],
        ['Employees', summary ? String(summary.employees) : '—', 'Active directory', UsersRound],
        ['Outstanding', summary ? formatCurrency(summary.outstanding) : 'Rs. 0', 'Receivables', CircleDollarSign],
        ['Collected this month', summary ? formatCurrency(summary.collected) : 'Rs. 0', 'Payments received', WalletCards]].map(([label, value, caption, Icon], index) => <div className={`metric-card${index === 2 ? ' metric-highlight' : ''}`} key={String(label)}><div className="metric-top"><span>{label}</span><Icon size={17} style={{ color: 'var(--teal)' }} /></div><div className="metric-number">{value}</div><div className="metric-caption">{caption}</div></div>)}
    </div>}
    <div className="grid two-col" style={{ marginBottom: 16 }}>
      <section className="panel" data-testid="panel-enrollment-trend"><div className="panel-head"><div><div className="panel-title">Enrollment movement</div><div className="panel-caption">Students registered across recent sessions</div></div><BarChart3 size={18} style={{ color: 'var(--teal)' }} /></div>{trend.length ? <div className="chart-wrap"><div className="chart-grid"><span /><span /><span /><span /></div><div className="bars">{trend.map((point) => <div className="bar-item" key={point.label}><div className="bar" style={{ height: `${Math.max((point.value / maxTrend) * 88, 2)}%` }} title={`${point.value} students`} /><div className="bar-label">{point.label}</div></div>)}</div></div> : <EmptyState icon={BarChart3} title="No enrollment trend yet" body="Once enrollment records are available, movement by session will appear here." />}</section>
      <section className="panel" data-testid="panel-attendance"><div className="panel-head"><div><div className="panel-title">Attendance today</div><div className="panel-caption">Across the active school community</div></div><Clock3 size={18} style={{ color: 'var(--saffron)' }} /></div><div className="donut-box">{attendance === undefined ? <EmptyState icon={Clock3} title="Attendance is quiet" body="No attendance snapshot has been reported yet." /> : <><div className="donut" style={{ background: `conic-gradient(var(--teal) 0deg, var(--teal) ${attendance * 3.6}deg, var(--donut-empty) ${attendance * 3.6}deg)` }}><div className="donut-inner"><div><div className="donut-number">{attendance}%</div><div className="donut-label">present</div></div></div></div><div className="legend"><span><i />Present</span><span><i className="off" />To follow up</span></div></>}</div></section>
    </div>
    <div className="grid three-col">
      <section className="panel" data-testid="panel-activity"><div className="panel-head"><div><div className="panel-title">Recent activity</div><div className="panel-caption">The latest changes across your school</div></div><Activity size={18} style={{ color: 'var(--teal)' }} /></div>{activityQuery.isLoading ? <div className="grid"><div className="skeleton" style={{ height: 48 }} /><div className="skeleton" style={{ height: 48 }} /><div className="skeleton" style={{ height: 48 }} /></div> : activityQuery.isError ? <ErrorState onRetry={() => activityQuery.refetch()} /> : activity.length ? <div className="activity-list">{activity.map((item) => <div className="activity-row" key={item.id} data-testid={`activity-row-${item.id}`}><div className="activity-dot"><Activity /></div><div><div className="activity-title">{item.title}</div><div className="activity-desc">{item.description}</div></div><div className="activity-time">{item.time}</div></div>)}</div> : <EmptyState icon={Activity} title="No activity to review" body="Actions from across admissions, people, and finance will be listed here." />}</section>
      <section className="panel" data-testid="panel-quick-actions"><div className="panel-head"><div><div className="panel-title">Quick actions</div><div className="panel-caption">Common work, one click away</div></div><ArrowUpRight size={17} style={{ color: 'var(--saffron)' }} /></div><div className="quick-actions"><Link href="/students" className="quick-action" data-testid="link-quick-student"><GraduationCap />New student</Link><Link href="/hr" className="quick-action" data-testid="link-quick-employee"><BriefcaseBusiness />Add employee</Link><Link href="/finance" className="quick-action" data-testid="link-quick-payment"><CreditCard />Record payment</Link><Link href="/settings" className="quick-action" data-testid="link-quick-settings"><Settings2 />School setup</Link></div></section>
      <section className="panel" data-testid="panel-guidance"><div className="panel-head"><div><div className="panel-title">Keep the picture clear</div><div className="panel-caption">A small operating ritual</div></div><BookOpen size={17} style={{ color: 'var(--rose)' }} /></div><p style={{ fontSize: 12, lineHeight: 1.65, color: 'var(--muted)' }}>Start with exceptions: open receivables, attendance follow-ups, and new admissions. Daymark keeps the context close so decisions stay human.</p><div style={{ marginTop: 20, display: 'flex', alignItems: 'center', gap: 8, color: 'var(--teal)', fontSize: 11, fontWeight: 700 }}><CheckCircle2 size={15} />Your workspace is ready</div></section>
    </div>
  </div>;
}

type StudentForm = { name: string; classId: string; sectionId: string; guardian: string; phone: string; status: string };
const blankStudent: StudentForm = { name: '', classId: '', sectionId: '', guardian: '', phone: '', status: 'active' };

function StudentModal({ editingId, onClose, onSaved }: { editingId: number | null; onClose: () => void; onSaved: () => void }) {
  const qc = useQueryClient();
  const [form, setForm] = useState<StudentForm>(blankStudent);
  const [notice, setNotice] = useState('');
  const [modalGrades, setModalGrades] = useState<{id: number; name: string; sections: {id: number; name: string}[]}[]>([]);
  const detailQuery = useGetStudent(editingId ?? 0, { query: { enabled: Boolean(editingId), queryKey: ['school-student-detail', editingId] } });
  const create = useCreateStudent();
  const update = useUpdateStudent();
  useEffect(() => { setupRequest('/setup/grades').then((d) => setModalGrades(d)).catch(() => {}); }, []);
  useEffect(() => { if (editingId && detailQuery.data) { const d = detailQuery.data; setForm({ name: d.name, classId: String(d.classId ?? ''), sectionId: String(d.sectionId ?? ''), guardian: d.guardian, phone: d.phone, status: d.status }); } else if (!editingId) setForm(blankStudent); }, [editingId, detailQuery.data]);
  const pending = create.isPending || update.isPending;
  const submit = (event: FormEvent) => { event.preventDefault(); setNotice(''); if (!form.name.trim() || !form.classId || !form.sectionId) { setNotice('Name, grade, and section are required.'); return; } const onSuccess = () => { refreshWorkspace(qc, [getListStudentsQueryKey(), getGetDashboardSummaryQueryKey(), getGetActivityQueryKey()]); onSaved(); }; const onError = () => setNotice('Student could not be saved. Please try again.'); if (editingId) update.mutate({ studentId: editingId, data: form }, { onSuccess, onError }); else create.mutate({ data: { name: form.name, classId: Number(form.classId), sectionId: Number(form.sectionId), guardian: form.guardian, phone: form.phone } }, { onSuccess, onError }); };
  return <div className="modal-backdrop" role="presentation" onClick={onClose}><div className="modal" role="dialog" aria-modal="true" aria-labelledby="student-dialog-title" onClick={(e) => e.stopPropagation()}><div className="modal-head"><div><div className="eyebrow">{editingId ? 'Admissions record' : 'New admission'}</div><div className="modal-title" id="student-dialog-title">{editingId ? 'Edit student' : 'Add a student'}</div></div><button className="close-btn" onClick={onClose} aria-label="Close dialog" data-testid="button-close-student-modal"><X size={16} /></button></div>{notice ? <div className="notice" data-testid="status-student-form">{notice}</div> : null}<form onSubmit={submit}><div className="form-grid"><label className="form-field full"><span className="form-label">Student name</span><input className="field" value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} placeholder="Full name" data-testid="input-student-name" /></label><label className="form-field"><span className="form-label">Grade</span><select className="field select" value={form.classId} onChange={(event) => setForm({ ...form, classId: event.target.value, sectionId: "" })} data-testid="select-student-grade"><option value="">Select grade</option>{modalGrades.map((g) => <option key={g.id} value={g.id}>{g.name}</option>)}</select></label><label className="form-field"><span className="form-label">Section</span><select className="field select" value={form.sectionId} onChange={(event) => setForm({ ...form, sectionId: event.target.value })} data-testid="select-student-section"><option value="">Select section</option>{(modalGrades.find((g) => String(g.id) === form.classId)?.sections ?? []).map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}</select></label><label className="form-field"><span className="form-label">Guardian</span><input className="field" value={form.guardian} onChange={(event) => setForm({ ...form, guardian: event.target.value })} placeholder="Guardian name" data-testid="input-student-guardian" /></label><label className="form-field full"><span className="form-label">Phone</span><input className="field" value={form.phone} onChange={(event) => setForm({ ...form, phone: event.target.value })} placeholder="Contact number" data-testid="input-student-phone" /></label></div><div className="modal-foot"><button type="button" className="btn btn-quiet" onClick={onClose} data-testid="button-cancel-student">Cancel</button><button className="btn btn-primary" type="submit" disabled={pending} data-testid="button-submit-student">{pending ? 'Saving…' : editingId ? 'Save changes' : 'Create student'}</button></div></form></div></div>;
}

function Students() {
  const [search, setSearch] = useState(''); const [modalId, setModalId] = useState<number | null | undefined>(undefined);
  const qc = useQueryClient();
  const deleteStudentMut = useDeleteStudent({ onSuccess: () => { refreshWorkspace(qc, [getListStudentsQueryKey(), getGetDashboardSummaryQueryKey(), getGetActivityQueryKey()]); } });
  const query = useListStudents({ search: search || undefined }); const students = query.data ?? [];
  return <div className="content"><PageHead eyebrow="Admissions & roster" title="Students" subtitle="A clear, admissions-ready directory for every learner." action={<button className="btn btn-primary" onClick={() => setModalId(null)} data-testid="button-add-student"><Plus size={15} /> Add student</button>} />
    {query.isError ? <ErrorState onRetry={() => query.refetch()} /> : <section className="panel" data-testid="panel-students"><div className="toolbar"><div className="search-wrap"><Search /><input className="search-input" type="search" placeholder="Search by name or admission number" value={search} onChange={(event) => setSearch(event.target.value)} data-testid="input-search-students" /></div><span className="mono" data-testid="text-student-count">{students.length} records</span></div>{query.isLoading ? <div className="grid"><div className="skeleton" style={{ height: 49 }} /><div className="skeleton" style={{ height: 49 }} /><div className="skeleton" style={{ height: 49 }} /></div> : students.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>Student</th><th>Class</th><th>Guardian</th><th>Joined</th><th>Status</th><th /></tr></thead><tbody>{students.map((student) => <tr key={student.id} data-testid={`row-student-${student.id}`}><td><div className="person"><div className="person-initial">{initials(student.name)}</div><div><div className="person-name">{student.name}</div><div className="person-meta">{student.admissionNo}</div></div></div></td><td>{student.className} <span style={{ color: 'var(--muted)' }}>{student.section}</span></td><td><div>{student.guardian}</div><div className="person-meta">{student.phone}</div></td><td>{student.joined}</td><td><span className={`status ${student.status}`}>{titleCase(student.status)}</span></td><td><button className="row-action" onClick={() => setModalId(student.id)} data-testid={`button-edit-student-${student.id}`} aria-label="Edit student"><Pencil size={14} /></button>{student.status?.toLowerCase() !== "active" ? <button className="row-action-delete" onClick={() => { if (window.confirm("Delete " + student.name + "? This cannot be undone.")) deleteStudentMut.mutate({ studentId: student.id }); }} data-testid={`button-delete-student-${student.id}`} aria-label="Delete student"><Trash2 size={14} /></button> : null}</td></tr>)}</tbody></table></div> : <EmptyState icon={GraduationCap} title="No students yet" body="Create the first student record to start building the roster." />}</section>}{modalId !== undefined ? <StudentModal editingId={modalId} onClose={() => setModalId(undefined)} onSaved={() => { setModalId(undefined); }} /> : null}</div>;
}

type InquiryForm = { studentName: string; dateOfBirth: string; gender: string; previousSchool: string; classId: string; sessionId: string; fatherFullName: string; fatherCnic: string; fatherDesignation: string; fatherPhone: string; motherFullName: string; motherCnic: string; motherDesignation: string; motherPhone: string; address: string; notes: string };
const blankInquiry: InquiryForm = { studentName: '', dateOfBirth: '', gender: '', previousSchool: '', classId: '', sessionId: '', fatherFullName: '', fatherCnic: '', fatherDesignation: '', fatherPhone: '', motherFullName: '', motherCnic: '', motherDesignation: '', motherPhone: '', address: '', notes: '' };

function InquiryModal({ context, onClose, onSaved }: { context?: AdmissionsContext; onClose: () => void; onSaved: () => void }) {
  const create = useCreateInquiry(); const [form, setForm] = useState<InquiryForm>(blankInquiry); const [notice, setNotice] = useState('');
  const submit = (event: FormEvent) => { event.preventDefault(); if (!form.studentName || !form.classId || !form.sessionId || !form.fatherFullName) { setNotice('Student, class, session, and father name are required.'); return; } create.mutate({ data: { ...form, classId: Number(form.classId), sessionId: Number(form.sessionId), dateOfBirth: form.dateOfBirth || undefined } }, { onSuccess: onSaved, onError: () => setNotice('Inquiry could not be saved. Please check the required details.') }); };
  const field = (name: keyof InquiryForm, label: string, full = false) => <label className={`form-field${full ? ' full' : ''}`}><span className="form-label">{label}</span><input className="field" value={form[name]} onChange={(event) => setForm({ ...form, [name]: event.target.value })} data-testid={`input-inquiry-${name}`} /></label>;
  return <div className="modal-backdrop" onClick={onClose}><div className="modal" style={{ width: 'min(760px, 100%)' }} role="dialog" aria-modal="true" onClick={(e) => e.stopPropagation()}><div className="modal-head"><div><div className="eyebrow">Admissions</div><div className="modal-title">New admission inquiry</div></div><button className="close-btn" onClick={onClose} aria-label="Close" data-testid="button-close-inquiry-form"><X size={16} /></button></div>{notice ? <div className="notice">{notice}</div> : null}{!context ? <div className="notice" data-testid="status-inquiry-context">Academic setup is still loading. Classes and sessions will appear here shortly.</div> : null}<form onSubmit={submit}><div className="form-grid">{field('studentName', 'Student full name', true)}<label className="form-field"><span className="form-label">Class / grade</span><select className="field select" value={form.classId} onChange={(event) => setForm({ ...form, classId: event.target.value })} data-testid="select-inquiry-class"><option value="">Select class</option>{context?.classes.map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</select></label><label className="form-field"><span className="form-label">Academic session</span><select className="field select" value={form.sessionId} onChange={(event) => setForm({ ...form, sessionId: event.target.value })} data-testid="select-inquiry-session"><option value="">Select session</option>{context?.sessions.map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</select></label>{field('dateOfBirth', 'Date of birth')}{field('gender', 'Gender')}{field('previousSchool', 'Previous school')}{field('fatherFullName', 'Father full name')}{field('fatherCnic', 'Father CNIC')}{field('fatherDesignation', 'Father designation')}{field('fatherPhone', 'Father phone')}{field('motherFullName', 'Mother full name')}{field('motherCnic', 'Mother CNIC')}{field('motherDesignation', 'Mother designation')}{field('motherPhone', 'Mother phone')}{field('address', 'Address', true)}{field('notes', 'Notes', true)}</div><div className="modal-foot"><button type="button" className="btn btn-quiet" onClick={onClose} data-testid="button-cancel-inquiry">Cancel</button><button className="btn btn-primary" type="submit" disabled={create.isPending} data-testid="button-submit-inquiry">{create.isPending ? 'Saving…' : 'Create inquiry'}</button></div></form></div></div>;
}

function InquiryDetail({ inquiry, context, onClose, onChanged }: { inquiry: Inquiry; context?: AdmissionsContext; onClose: () => void; onChanged: () => void }) {
  const updateFees = useUpdateInquiryFees(); const invoice = useGenerateInquiryInvoice(); const enroll = useEnrollInquiry(); const remove = useDeleteInquiry(); const [fees, setFees] = useState(inquiry.fees.map((fee) => ({ feeHeadId: fee.feeHeadId, amount: String(fee.amount) }))); const [notice, setNotice] = useState('');
  const saveFees = () => updateFees.mutate({ inquiryId: inquiry.id, data: { fees: fees.filter((fee) => Number(fee.amount) >= 0).map((fee) => ({ feeHeadId: fee.feeHeadId, amount: Number(fee.amount) })) } }, { onSuccess: onChanged, onError: () => setNotice('Fee changes could not be saved.') });
  const generate = () => invoice.mutate({ inquiryId: inquiry.id }, { onSuccess: onChanged, onError: () => setNotice('Select fees before generating an invoice.') });
  const enrollNow = () => enroll.mutate({ inquiryId: inquiry.id }, { onSuccess: onChanged, onError: () => setNotice('The admission invoice must be fully paid before enrollment.') });
  const deleteNow = () => { if (!window.confirm('Remove this inquiry? This action cannot be undone.')) return; remove.mutate({ inquiryId: inquiry.id }, { onSuccess: onChanged, onError: () => setNotice('This inquiry could not be removed.') }); };
  const printInvoice = () => window.print();
  return <div className="modal-backdrop" onClick={onClose}><div className="modal print-area" style={{ width: 'min(760px, 100%)' }} role="dialog" aria-modal="true" onClick={(e) => e.stopPropagation()}><div className="modal-head"><div><div className="eyebrow">{inquiry.inquiryNo} — {inquiry.status}</div><div className="modal-title">Admission inquiry</div></div><button className="close-btn" onClick={onClose} aria-label="Close" data-testid="button-close-inquiry-detail"><X size={16} /></button></div>{notice ? <div className="notice">{notice}</div> : null}<div className="detail-grid"><div><div className="detail-label">Student</div><div>{inquiry.studentName}</div></div><div><div className="detail-label">Class</div><div>{inquiry.className}</div></div><div><div className="detail-label">Session</div><div>{inquiry.sessionName}</div></div><div><div className="detail-label">Father</div><div>{inquiry.fatherFullName}</div></div><div><div className="detail-label">Father phone</div><div>{inquiry.fatherPhone || 'No phone'}</div></div><div><div className="detail-label">Father CNIC</div><div>{inquiry.fatherCnic || 'No CNIC'}</div></div><div><div className="detail-label">Mother</div><div>{inquiry.motherFullName || 'Not provided'}</div></div><div><div className="detail-label">Mother phone</div><div>{inquiry.motherPhone || 'No phone'}</div></div><div><div className="detail-label">Mother CNIC</div><div>{inquiry.motherCnic || 'No CNIC'}</div></div>{inquiry.address ? <div><div className="detail-label">Address</div><div>{inquiry.address}</div></div> : null}{inquiry.notes ? <div><div className="detail-label">Notes</div><div>{inquiry.notes}</div></div> : null}</div><div style={{ marginTop: 20 }}><div className="detail-label" style={{ marginBottom: 8 }}>Fee adjustments</div><div className="tag-list">{fees.map((fee, index) => <label className="fee-row" key={fee.feeHeadId}><span>{context?.feeHeads?.find((h) => h.id === fee.feeHeadId)?.name || `Head ${fee.feeHeadId}`}</span><input className="field fee-amount" type="number" min="0" step="0.01" value={fee.amount} onChange={(event) => { const updated = [...fees]; updated[index] = { ...updated[index], amount: event.target.value }; setFees(updated); }} data-testid={`input-inquiry-fee-${index}`} /></label>)}{fees.length ? <button className="btn btn-quiet" onClick={saveFees} disabled={updateFees.isPending} data-testid="button-save-inquiry-fees">{updateFees.isPending ? 'Saving…' : 'Save fee changes'}</button> : null}</div></div><div style={{ marginTop: 20, display: 'flex', gap: 8, flexWrap: 'wrap' }}><button className="btn btn-quiet" onClick={printInvoice} data-testid="button-print-inquiry">Print</button><button className="btn btn-quiet" onClick={generate} disabled={invoice.isPending} data-testid="button-generate-invoice">{invoice.isPending ? 'Generating…' : 'Generate invoice'}</button>{inquiry.balance === 0 && inquiry.total > 0 ? <button className="btn btn-primary" onClick={enrollNow} disabled={enroll.isPending} data-testid="button-enroll-student">{enroll.isPending ? 'Enrolling…' : 'Enroll as student'}</button> : null}<button className="btn btn-danger" onClick={deleteNow} disabled={remove.isPending} data-testid="button-remove-inquiry">{remove.isPending ? 'Removing…' : 'Remove inquiry'}</button></div></div></div>;
}

function Admissions() {
  const qc = useQueryClient(); const contextQuery = useGetAdmissionsContext(); const inquiriesQuery = useListInquiries(); const [modal, setModal] = useState<'new' | number | null>(null); const inquiries = inquiriesQuery.data ?? [];
  const refresh = () => { refreshWorkspace(qc, [getListInquiriesQueryKey(), getListInvoicesQueryKey(), getListStudentsQueryKey(), getGetDashboardSummaryQueryKey(), getGetActivityQueryKey()]); setModal(null); };
  return <div className="content"><PageHead eyebrow="Admissions workspace" title="Inquiries before enrollment." subtitle="Capture family details, price the admission, collect payment, then enroll with confidence." action={<button className="btn btn-primary" onClick={() => setModal('new')} data-testid="button-add-inquiry"><Plus size={15} /> New inquiry</button>} />{inquiriesQuery.isError ? <ErrorState onRetry={() => inquiriesQuery.refetch()} /> : <section className="panel" data-testid="panel-inquiries"><div className="panel-head"><div><div className="panel-title">Admission inquiries</div><div className="panel-caption">A student is created only after the admission balance is settled.</div></div><span className="mono">{inquiries.length} records</span></div>{inquiriesQuery.isLoading ? <LoadingCards /> : inquiries.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>Inquiry</th><th>Class / session</th><th>Parent</th><th>Fees</th><th>Balance</th><th>Status</th><th /></tr></thead><tbody>{inquiries.map((inquiry) => <tr key={inquiry.id}><td><div className="person"><div className="person-initial">{initials(inquiry.studentName)}</div><div><div className="person-name">{inquiry.studentName}</div><div className="person-meta">{inquiry.inquiryNo}</div></div></div></td><td>{inquiry.className}<div className="person-meta">{inquiry.sessionName}</div></td><td><div>{inquiry.fatherFullName}</div><div className="person-meta">{inquiry.fatherPhone || 'No phone'}</div></td><td>{formatCurrency(inquiry.total)}</td><td>{formatCurrency(inquiry.balance)}</td><td><span className={`status ${inquiry.balance === 0 && inquiry.total > 0 ? 'paid' : inquiry.status === 'Enrolled' ? 'active' : 'pending'}`}>{inquiry.balance === 0 && inquiry.total > 0 ? 'Paid' : inquiry.status === 'Enrolled' ? 'Enrolled' : inquiry.status === 'Invoiced' ? 'Invoiced' : 'Inquiry'}</span></td><td><button className="row-action" onClick={() => setModal(inquiry.id)}>Open</button></td></tr>)}</tbody></table></div> : <EmptyState icon={ClipboardList} title="No admission inquiries yet" body="Start with the family and academic details, then build the invoice from the selected fee heads." />}</section>}{modal === 'new' ? <InquiryModal context={contextQuery.data} onClose={() => setModal(null)} onSaved={refresh} /> : typeof modal === 'number' ? <InquiryRecord inquiryId={modal} context={contextQuery.data} onClose={() => setModal(null)} onChanged={refresh} /> : null}</div>;
}

function InquiryRecord({ inquiryId, context, onClose, onChanged }: { inquiryId: number; context?: AdmissionsContext; onClose: () => void; onChanged: () => void }) {
  const query = useGetInquiry(inquiryId); return query.isLoading ? <div className="modal-backdrop" onClick={onClose}><div className="modal" onClick={(e) => e.stopPropagation()}><LoadingCards /></div></div> : query.isError ? <div className="modal-backdrop" onClick={onClose}><div className="modal" onClick={(e) => e.stopPropagation()}><ErrorState onRetry={() => query.refetch()} /></div></div> : query.data ? <InquiryDetail inquiry={query.data} context={context} onClose={onClose} onChanged={onChanged} /> : null;
}

type EmployeeForm = { name: string; designation: string; department: string; phone: string };
function EmployeeModal({ onClose, onSaved }: { onClose: () => void; onSaved: () => void }) {
  const qc = useQueryClient(); const create = useCreateEmployee(); const [form, setForm] = useState<EmployeeForm>({ name: '', designation: '', department: '', phone: '' }); const [notice, setNotice] = useState('');
  const submit = (event: FormEvent) => { event.preventDefault(); if (!form.name.trim() || !form.designation.trim()) { setNotice('Name and designation are required.'); return; } create.mutate({ data: form }, { onSuccess: () => { refreshWorkspace(qc, [getListEmployeesQueryKey(), getGetDashboardSummaryQueryKey(), getGetActivityQueryKey()]); onSaved(); }, onError: () => setNotice('Employee could not be saved. Please try again.') }); };
  return <div className="modal-backdrop" onClick={onClose}><div className="modal" role="dialog" aria-modal="true" aria-labelledby="employee-dialog-title" onClick={(e) => e.stopPropagation()}><div className="modal-head"><div><div className="eyebrow">People operations</div><div className="modal-title" id="employee-dialog-title">Add an employee</div></div><button className="close-btn" onClick={onClose} aria-label="Close dialog" data-testid="button-close-employee-modal"><X size={16} /></button></div>{notice ? <div className="notice" data-testid="status-employee-form">{notice}</div> : null}<form onSubmit={submit}><div className="form-grid"><label className="form-field full"><span className="form-label">Full name</span><input className="field" value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} placeholder="Employee name" data-testid="input-employee-name" /></label><label className="form-field"><span className="form-label">Designation</span><input className="field" value={form.designation} onChange={(event) => setForm({ ...form, designation: event.target.value })} placeholder="e.g. Science teacher" data-testid="input-employee-designation" /></label><label className="form-field"><span className="form-label">Department</span><input className="field" value={form.department} onChange={(event) => setForm({ ...form, department: event.target.value })} placeholder="e.g. Academics" data-testid="input-employee-department" /></label><label className="form-field full"><span className="form-label">Phone</span><input className="field" value={form.phone} onChange={(event) => setForm({ ...form, phone: event.target.value })} placeholder="Contact number" data-testid="input-employee-phone" /></label></div><div className="modal-foot"><button type="button" className="btn btn-quiet" onClick={onClose} data-testid="button-cancel-employee">Cancel</button><button className="btn btn-primary" type="submit" disabled={create.isPending} data-testid="button-submit-employee">{create.isPending ? 'Saving…' : 'Create employee'}</button></div></form></div></div>;
}

function HR() {
  const [showModal, setShowModal] = useState(false); const qc = useQueryClient();
  const deleteEmpMut = useDeleteEmployee({ onSuccess: () => { refreshWorkspace(qc, [getListEmployeesQueryKey(), getGetDashboardSummaryQueryKey(), getGetActivityQueryKey()]); } });
  const query = useListEmployees(); const employees = query.data ?? [];
  const average = employees.length ? Math.round(employees.reduce((sum, employee) => sum + employee.attendance, 0) / employees.length) : undefined;
  return <div className="content"><PageHead eyebrow="People operations" title="Your people" subtitle="Keep the team directory and today’s attendance in the same view." action={<button className="btn btn-primary" onClick={() => setShowModal(true)} data-testid="button-add-employee"><Plus size={15} /> Add employee</button>} />
    {query.isError ? <ErrorState onRetry={() => query.refetch()} /> : <section className="panel" data-testid="panel-employees"><div className="toolbar"><div className="search-wrap"><Search /><input className="search-input" type="search" placeholder="Search by name or designation" data-testid="input-search-employees" /></div><span className="mono" data-testid="text-employee-count">{employees.length} records</span></div>{query.isLoading ? <div className="grid"><div className="skeleton" style={{ height: 49 }} /><div className="skeleton" style={{ height: 49 }} /></div> : employees.length ? <div className="grid two-col" style={{ marginBottom: 16 }}>{employees.length ? <div className="metric-card"><div className="metric-top"><span>Average attendance</span><Clock3 size={17} style={{ color: 'var(--saffron)' }} /></div><div className="metric-number" data-testid="text-average-attendance">{average === undefined ? '—' : `${average}%`}</div><div className="metric-caption">Across all staff today</div></div> : null}<div className="metric-card"><div className="metric-top"><span>Total employees</span><UsersRound size={17} style={{ color: 'var(--teal)' }} /></div><div className="metric-number">{employees.length}</div><div className="metric-caption">Active directory</div></div></div> : null}{query.isLoading ? null : employees.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>Employee</th><th>Designation</th><th>Department</th><th>Phone</th><th>Status</th><th /></tr></thead><tbody>{employees.map((employee) => <tr key={employee.id} data-testid={`row-employee-${employee.id}`}><td><div className="person"><div className="person-initial">{initials(employee.name)}</div><div><div className="person-name">{employee.name}</div><div className="person-meta">{employee.designation}</div></div></div></td><td>{employee.designation}</td><td>{employee.department || '—'}</td><td>{employee.phone || '—'}</td><td><span className={`status ${employee.status}`}>{titleCase(employee.status)}</span></td><td>{employee.status?.toLowerCase() !== "present" ? <button className="row-action-delete" onClick={() => { if (window.confirm("Delete " + employee.name + "? This cannot be undone.")) deleteEmpMut.mutate({ employeeId: employee.id }); }} data-testid={`button-delete-employee-${employee.id}`} aria-label="Delete employee"><Trash2 size={14} /></button> : null}</td></tr>)}</tbody></table></div> : <EmptyState icon={UsersRound} title="No employees yet" body="Add the first team member to begin tracking people operations." />}</section>}{showModal ? <EmployeeModal onClose={() => setShowModal(false)} onSaved={() => setShowModal(false)} /> : null}</div>;
}

function PaymentModal({ onClose, onSaved, invoiceId, amount }: { onClose: () => void; onSaved: () => void; invoiceId?: number; amount?: number }) {
  const qc = useQueryClient(); const record = useRecordPayment(); const [form, setForm] = useState({ invoiceId: invoiceId ? String(invoiceId) : '', amount: amount ? String(amount) : '', method: 'bank transfer', paidAt: new Date().toISOString().slice(0, 10) }); const [notice, setNotice] = useState('');
  const submit = (event: FormEvent) => { event.preventDefault(); const amount = Number(form.amount); const parsedInvoiceId = Number(form.invoiceId); if (!Number.isInteger(parsedInvoiceId) || parsedInvoiceId <= 0 || !Number.isFinite(amount) || amount <= 0 || !form.paidAt) { setNotice('Enter a valid invoice, a payment amount, and a payment date.'); return; } record.mutate({ data: { invoiceId: parsedInvoiceId, amount, method: form.method, paidAt: form.paidAt } }, { onSuccess: () => { refreshWorkspace(qc, [getListInvoicesQueryKey(), getListInquiriesQueryKey(), getGetDashboardSummaryQueryKey(), getGetActivityQueryKey()]); onSaved(); }, onError: () => setNotice('Payment could not be recorded. Please try again.') }); };
  return <div className="modal-backdrop" onClick={onClose}><div className="modal" role="dialog" aria-modal="true" aria-labelledby="payment-dialog-title" onClick={(e) => e.stopPropagation()}><div className="modal-head"><div><div className="eyebrow">Receivables</div><div className="modal-title" id="payment-dialog-title">Record a payment</div></div><button className="close-btn" onClick={onClose} aria-label="Close dialog" data-testid="button-close-payment-modal"><X size={16} /></button></div>{notice ? <div className="notice">{notice}</div> : null}<form onSubmit={submit}><div className="form-grid"><label className="form-field"><span className="form-label">Invoice ID</span><input className="field" type="number" value={form.invoiceId} onChange={(event) => setForm({ ...form, invoiceId: event.target.value })} placeholder="Invoice ID" data-testid="input-payment-invoice" /></label><label className="form-field"><span className="form-label">Amount</span><input className="field" type="number" min="0" step="0.01" value={form.amount} onChange={(event) => setForm({ ...form, amount: event.target.value })} placeholder="0.00" data-testid="input-payment-amount" /></label><label className="form-field"><span className="form-label">Method</span><select className="field select" value={form.method} onChange={(event) => setForm({ ...form, method: event.target.value })} data-testid="select-payment-method"><option value="bank transfer">Bank transfer</option><option value="cash">Cash</option><option value="card">Card</option><option value="online">Online</option></select></label><label className="form-field"><span className="form-label">Paid on</span><input className="field" type="date" value={form.paidAt} onChange={(event) => setForm({ ...form, paidAt: event.target.value })} data-testid="input-payment-date" /></label></div><div className="modal-foot"><button type="button" className="btn btn-quiet" onClick={onClose} data-testid="button-cancel-payment">Cancel</button><button className="btn btn-primary" type="submit" disabled={record.isPending} data-testid="button-submit-payment">{record.isPending ? 'Recording…' : 'Record payment'}</button></div></form></div></div>;
}

function JournalModal({ onClose, onSaved }: { onClose: () => void; onSaved: () => void }) {
  const qc = useQueryClient(); const create = useCreateJournalEntry(); const [form, setForm] = useState({ date: new Date().toISOString().slice(0, 10), description: '', lines: [{ account: '', debit: '', credit: '' }, { account: '', debit: '', credit: '' }] }); const [notice, setNotice] = useState('');
  const submit = (event: FormEvent) => { event.preventDefault(); const lines = form.lines.map((line) => ({ account: line.account, debit: Number(line.debit || 0), credit: Number(line.credit || 0) })); const debitTotal = lines.reduce((sum, line) => sum + line.debit, 0); const creditTotal = lines.reduce((sum, line) => sum + line.credit, 0); if (!form.description.trim() || lines.some((line) => !line.account.trim()) || lines.every((line) => line.debit === 0 && line.credit === 0)) { setNotice('Add a description, accounts, and at least one amount.'); return; } if (Math.abs(debitTotal - creditTotal) > 0.005) { setNotice('Debits and credits must balance before saving.'); return; } create.mutate({ data: { date: form.date, description: form.description.trim(), lines } }, { onSuccess: () => { refreshWorkspace(qc, [getGetDashboardSummaryQueryKey(), getGetActivityQueryKey()]); onSaved(); }, onError: () => setNotice('Journal entry could not be saved. Check that debits and credits balance.') }); };
  return <div className="modal-backdrop" onClick={onClose}><div className="modal" role="dialog" aria-modal="true" aria-labelledby="journal-dialog-title" onClick={(e) => e.stopPropagation()}><div className="modal-head"><div><div className="eyebrow">Accounting</div><div className="modal-title" id="journal-dialog-title">New journal entry</div></div><button className="close-btn" onClick={onClose} aria-label="Close dialog" data-testid="button-close-journal-modal"><X size={16} /></button></div>{notice ? <div className="notice">{notice}</div> : null}<form onSubmit={submit}><div className="form-grid"><label className="form-field"><span className="form-label">Date</span><input className="field" type="date" value={form.date} onChange={(event) => setForm({ ...form, date: event.target.value })} data-testid="input-journal-date" /></label><label className="form-field"><span className="form-label">Description</span><input className="field" value={form.description} onChange={(event) => setForm({ ...form, description: event.target.value })} placeholder="Reason for entry" data-testid="input-journal-description" /></label></div><div style={{ marginTop: 18 }}><div className="form-label" style={{ marginBottom: 8 }}>Lines</div><div className="journal-lines">{form.lines.map((line, index) => <div className="journal-line" key={index}><input className="field" value={line.account} onChange={(event) => setForm({ ...form, lines: form.lines.map((item, itemIndex) => itemIndex === index ? { ...item, account: event.target.value } : item) })} placeholder="Account" data-testid={`input-journal-account-${index}`} /><input className="field" type="number" value={line.debit} onChange={(event) => setForm({ ...form, lines: form.lines.map((item, itemIndex) => itemIndex === index ? { ...item, debit: event.target.value } : item) })} placeholder="Debit" data-testid={`input-journal-debit-${index}`} /><input className="field" type="number" value={line.credit} onChange={(event) => setForm({ ...form, lines: form.lines.map((item, itemIndex) => itemIndex === index ? { ...item, credit: event.target.value } : item) })} placeholder="Credit" data-testid={`input-journal-credit-${index}`} /></div>)}</div></div><div className="modal-foot"><button type="button" className="btn btn-quiet" onClick={onClose} data-testid="button-cancel-journal">Cancel</button><button className="btn btn-primary" type="submit" disabled={create.isPending} data-testid="button-submit-journal">{create.isPending ? 'Saving…' : 'Save journal entry'}</button></div></form></div></div>;
}

function Finance() {
  const query = useListInvoices(); const invoices = query.data ?? []; const [modal, setModal] = useState<'payment' | 'journal' | null>(null); const [paymentInvoiceId, setPaymentInvoiceId] = useState<number | undefined>(); const [paymentAmount, setPaymentAmount] = useState<number | undefined>(); const [status, setStatus] = useState('');
  const value = invoices.reduce((sum, invoice) => sum + invoice.amount, 0); const open = invoices.filter((invoice) => invoice.status?.toLowerCase() !== 'paid').reduce((sum, invoice) => sum + invoice.amount, 0); const paid = value - open;
  return <div className="content"><PageHead eyebrow="Finance desk" title="Money, made legible." subtitle="Receivables and accounting entries in one composed view." action={<button className="btn btn-primary" onClick={() => { setPaymentInvoiceId(undefined); setPaymentAmount(undefined); setModal('payment'); }} data-testid="button-record-payment"><CreditCard size={15} /> Record payment</button>} />{status ? <div className="notice" data-testid="status-finance">{status}</div> : null}{query.isError ? <ErrorState onRetry={() => query.refetch()} /> : <><div className="finance-stats"><div className="finance-stat"><span>Invoice value</span><strong data-testid="text-invoice-value">{formatCurrency(value)}</strong></div><div className="finance-stat"><span>Open receivables</span><strong data-testid="text-open-receivables">{formatCurrency(open)}</strong></div><div className="finance-stat"><span>Settled value</span><strong data-testid="text-settled-value">{formatCurrency(paid)}</strong></div></div><section className="panel" data-testid="panel-invoices"><div className="panel-head"><div><div className="panel-title">Invoices</div><div className="panel-caption">Collection worklist for the school office</div></div><button className="btn btn-quiet" onClick={() => setModal('journal')} data-testid="button-new-journal"><FileText size={14} /> Journal entry</button></div>{query.isLoading ? <div className="grid"><div className="skeleton" style={{ height: 49 }} /><div className="skeleton" style={{ height: 49 }} /></div> : invoices.length ? <div className="table-scroll"><table className="data-table"><thead><tr><th>Invoice</th><th>Student</th><th>Category</th><th>Amount</th><th>Due date</th><th>Status</th><th /></tr></thead><tbody>{invoices.map((invoice) => <tr key={invoice.id} data-testid={`row-invoice-${invoice.id}`}><td><span style={{ fontFamily: 'var(--font-mono)', fontSize: 11 }}>{invoice.invoiceNo}</span></td><td className="person-name">{invoice.student}</td><td>{invoice.category}</td><td style={{ fontFamily: 'var(--font-mono)', fontSize: 11 }}>{formatCurrency(invoice.amount)}</td><td>{invoice.dueDate}</td><td><span className={`status ${invoice.status}`}>{titleCase(invoice.status)}</span></td><td>{invoice.status?.toLowerCase() !== 'paid' ? <button className="row-action" onClick={() => { setPaymentInvoiceId(invoice.id); setPaymentAmount(invoice.amount); setModal('payment'); }} data-testid={`button-pay-invoice-${invoice.id}`}>Collect</button> : <CheckCircle2 size={15} color="var(--teal)" />}</td></tr>)}</tbody></table></div> : <EmptyState icon={WalletCards} title="No invoices to collect" body="When invoices are raised, open receivables and collection actions will land here." action={<button className="btn btn-quiet" onClick={() => setModal('journal')} data-testid="button-empty-new-journal"><FileText size={14} /> New journal entry</button>} />}</section></>}{modal === 'payment' ? <PaymentModal invoiceId={paymentInvoiceId} amount={paymentAmount} onClose={() => setModal(null)} onSaved={() => { setModal(null); setStatus('Payment recorded. Invoice list refreshed.'); }} /> : null}{modal === 'journal' ? <JournalModal onClose={() => setModal(null)} onSaved={() => { setModal(null); setStatus('Journal entry saved.'); }} /> : null}</div>;
}

type SetupState = { school: { name: string; academicYear: string }; classes: { id: number; name: string }[]; sessions: { id: number; name: string; startDate: string; endDate: string; isActive: boolean }[]; feeHeads: { id: number; name: string; amount: number; isActive: boolean }[]; structures: { classId: number; sessionId: number; feeHeadId: number; amount: number }[]; modules: Record<string, boolean>; designations: { id: number; name: string; isSystem: boolean }[] };
function PersistentSettings() {
  const [data, setData] = useState<SetupState | null>(null); const [className, setClassName] = useState(''); const [grades, setGrades] = useState<{id: number; name: string; sections: {id: number; name: string}[]}[]>([]); const [gradeNameInput, setGradeNameInput] = useState(''); const [session, setSession] = useState({ name: '', startDate: '', endDate: '', isActive: true }); const [feeHead, setFeeHead] = useState({ name: '', amount: '' }); const [designationName, setDesignationName] = useState(''); const [selectedClass, setSelectedClass] = useState(''); const [selectedSession, setSelectedSession] = useState(''); const [structure, setStructure] = useState<Record<string, string>>({}); const [notice, setNotice] = useState(''); const [error, setError] = useState('');
  const load = async () => { try { const result = await setupRequest('/setup'); const [modules, designations] = await Promise.all([setupRequest('/setup/modules').catch(() => ({ admissions: true, people: true, finance: true, attendance: true })), setupRequest('/setup/designations').catch(() => [])]); const gradesData = await setupRequest('/setup/grades').catch(() => []); setGrades(gradesData); setData({ ...result, modules, designations }); setError(''); } catch (e) { setError(e instanceof Error ? e.message : 'Setup could not load'); } };
  useEffect(() => { void load(); }, []);
  useEffect(() => { if (!data) return; if (!selectedClass && data.classes[0]) setSelectedClass(String(data.classes[0].id)); if (!selectedSession && data.sessions[0]) setSelectedSession(String(data.sessions[0].id)); }, [data, selectedClass, selectedSession]);
  useEffect(() => { if (!data || !selectedClass || !selectedSession) return; const values: Record<string, string> = {}; data.feeHeads.forEach((head) => { const item = data.structures.find((entry) => entry.classId === Number(selectedClass) && entry.sessionId === Number(selectedSession) && entry.feeHeadId === head.id); values[String(head.id)] = item ? String(item.amount) : ''; }); setStructure(values); }, [data, selectedClass, selectedSession]);
  const run = async (action: () => Promise<unknown>, success: string) => { try { await action(); await load(); setNotice(success); setError(''); } catch (e) { setError(e instanceof Error ? e.message : 'Could not save setup'); } };
  if (!data)   return <div className="content"><PageHead eyebrow="School setup" title="Make it yours." subtitle="Classes, sessions, and fee structures now save to the school database." /><div className="grid"><div className="skeleton" style={{ height: 49 }} /><div className="skeleton" style={{ height: 49 }} /></div></div>; return <div className="content"><PageHead eyebrow="School setup" title="Make it yours." subtitle="Classes, sessions, and fee structures now save to the school database." action={<button className="btn btn-primary" onClick={() => void run(() => setupRequest('/setup/school', { method: 'PATCH', body: JSON.stringify({ name: data!.school.name, academicYear: data!.school.academicYear }) }), 'School identity saved.')} data-testid="button-save-settings"><CheckCircle2 size={15} /> Save setup</button>} />{notice ? <div className="notice" data-testid="status-settings-saved">{notice}</div> : null}{error ? <div className="notice" style={{ color: 'var(--rose)' }}>{error}</div> : null}<div className="settings-cards">
  <div className="settings-card"><div className="settings-card-head"><div className="settings-card-title">School identity</div></div><div className="settings-card-body"><label className="form-field"><span className="form-label">School name</span><input className="field" value={data.school.name} onChange={(e) => setData({ ...data, school: { ...data.school, name: e.target.value } })} data-testid="input-school-name" /></label><label className="form-field"><span className="form-label">Academic year</span><input className="field" value={data.school.academicYear} onChange={(e) => setData({ ...data, school: { ...data.school, academicYear: e.target.value } })} data-testid="input-academic-session" /></label></div></div>
  <div className="settings-card"><div className="settings-card-head"><div className="settings-card-title">Academic sessions</div><div className="settings-card-desc">Manage school terms and date ranges</div></div><div className="settings-card-body"><table className="data-table" style={{ fontSize: 12 }}><thead><tr><th>Session</th><th>Start</th><th>End</th><th>Active</th><th /></tr></thead><tbody>{data.sessions.map((s) => <tr key={s.id}><td>{s.name}</td><td>{s.startDate}</td><td>{s.endDate}</td><td><span className={'status ' + (s.isActive ? 'active' : '')}>{s.isActive ? 'Active' : 'Inactive'}</span></td><td style={{ display: 'flex', gap: 4 }}><button className="row-action" onClick={() => { const name = window.prompt('Session name', s.name); if (name?.trim()) void run(() => setupRequest('/setup/sessions/' + s.id, { method: 'PATCH', body: JSON.stringify({ name: name.trim() }) }), 'Session updated.'); }} data-testid={'button-edit-session-' + s.id} aria-label={'Edit session ' + s.name}><Pencil size={13} /></button><button className="row-action-delete" onClick={() => { if (window.confirm('Delete session "' + s.name + '"?')) void run(() => setupRequest('/setup/sessions/' + s.id, { method: 'DELETE' }), 'Session deleted.'); }} data-testid={'button-delete-session-' + s.id} aria-label={'Delete session ' + s.name}><Trash2 size={13} /></button></td></tr>)}</tbody></table><div className="settings-add-row"><input className="field" value={session.name} onChange={(e) => setSession({ ...session, name: e.target.value })} placeholder="Session name" data-testid="input-session-name" /><input className="field" type="date" value={session.startDate} onChange={(e) => setSession({ ...session, startDate: e.target.value })} data-testid="input-session-start" /><input className="field" type="date" value={session.endDate} onChange={(e) => setSession({ ...session, endDate: e.target.value })} data-testid="input-session-end" /><button className="btn btn-quiet btn-sm" onClick={() => { if (!session.name || !session.startDate || !session.endDate) return; void run(() => setupRequest('/setup/sessions', { method: 'POST', body: JSON.stringify(session) }), 'Session created.'); setSession({ name: '', startDate: '', endDate: '', isActive: true }); }} data-testid="button-add-session"><Plus size={14} /></button></div></div></div>
  <div className="settings-card"><div className="settings-card-head"><div className="settings-card-title">Fee heads</div><div className="settings-card-desc">Categories for billing (tuition, transport, etc.)</div></div><div className="settings-card-body"><div className="fee-head-grid">{data.feeHeads.filter((h) => h.isActive !== false).map((head) => <div className="fee-head-item" key={head.id}><div className="fee-head-info"><span className="fee-head-name">{head.name}</span><span className="fee-head-amount">{formatCurrency(head.amount)}</span></div><div className="fee-head-actions"><button className="row-action" onClick={() => { const name = window.prompt('Fee head name', head.name); const amount = window.prompt('Fee amount', head.amount); if (name?.trim() && amount !== null) void run(() => setupRequest('/setup/fee-heads/' + head.id, { method: 'PATCH', body: JSON.stringify({ name: name.trim(), amount: Number(amount) }) }), 'Fee head updated.'); }} data-testid={'button-edit-fee-head-' + head.id} aria-label={'Edit fee head ' + head.name}><Pencil size={12} /></button><button className="row-action-delete" onClick={() => { if (window.confirm('Remove "' + head.name + '"?')) void run(() => setupRequest('/setup/fee-heads/' + head.id, { method: 'DELETE' }), 'Fee head removed.'); }} data-testid={'button-delete-fee-head-' + head.id} aria-label={'Delete fee head ' + head.name}><Trash2 size={12} /></button></div></div>)}</div><div className="settings-add-row"><input className="field" value={feeHead.name} onChange={(e) => setFeeHead({ ...feeHead, name: e.target.value })} placeholder="Fee name" data-testid="input-fee-head-name" /><input className="field" type="number" min="0" value={feeHead.amount} onChange={(e) => setFeeHead({ ...feeHead, amount: e.target.value })} placeholder="Amount" data-testid="input-fee-head-amount" /><button className="btn btn-quiet btn-sm" onClick={() => { if (!feeHead.name || !feeHead.amount) return; void run(() => setupRequest('/setup/fee-heads', { method: 'POST', body: JSON.stringify({ name: feeHead.name, amount: Number(feeHead.amount) }) }), 'Fee head added.'); setFeeHead({ name: '', amount: '' }); }} data-testid="button-add-fee-head"><Plus size={14} /></button></div></div></div>
  <div className="settings-card"><div className="settings-card-head"><div className="settings-card-title">Fee structure</div><div className="settings-card-desc">Set amounts per grade and session</div></div><div className="settings-card-body"><div className="settings-add-row" style={{ marginBottom: 14 }}><label className="form-field" style={{ flex: 1 }}><span className="form-label">Grade</span><select className="field select" value={selectedClass} onChange={(e) => setSelectedClass(e.target.value)} data-testid="select-structure-class">{data.classes.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label className="form-field" style={{ flex: 1 }}><span className="form-label">Session</span><select className="field select" value={selectedSession} onChange={(e) => setSelectedSession(e.target.value)} data-testid="select-structure-session">{data.sessions.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}</select></label></div><div className="fee-structure-grid">{data.feeHeads.filter((h) => h.isActive !== false).map((head) => <div className="fee-structure-item" key={head.id}><span className="fee-structure-label">{head.name}</span><input className="field fee-structure-input" type="number" min="0" value={structure[String(head.id)] ?? ''} onChange={(e) => setStructure({ ...structure, [String(head.id)]: e.target.value })} placeholder={String(head.amount)} data-testid={'input-structure-' + head.id} /></div>)}</div><button className="btn btn-quiet btn-sm" style={{ marginTop: 12 }} onClick={() => { const entries = data.feeHeads.filter((h) => h.isActive !== false).map((head) => ({ classId: Number(selectedClass), sessionId: Number(selectedSession), feeHeadId: head.id, amount: Number(structure[String(head.id)] || 0) })).filter((e) => e.amount > 0); if (!entries.length) return; void run(() => setupRequest('/setup/structures', { method: 'POST', body: JSON.stringify({ entries }) }), 'Fee structure saved.'); }} data-testid="button-save-structure"><CheckCircle2 size={14} /> Save structure</button></div></div>
  <div className="settings-card"><div className="settings-card-head"><div className="settings-card-title">Module toggles</div><div className="settings-card-desc">Enable or disable features for the school</div></div><div className="settings-card-body">{Object.entries(data.modules).map(([key, value]) => <div className="toggle-row" key={key}><div className="toggle-copy"><strong>{titleCase(key)}</strong><span>{key === 'admissions' ? 'Inquiry and enrollment pipeline' : key === 'people' ? 'Employee directory and attendance' : key === 'finance' ? 'Invoices, payments, and journal entries' : 'Attendance tracking'}</span></div><label className="switch"><input type="checkbox" checked={Boolean(value)} onChange={(e) => void run(() => setupRequest('/setup/modules', { method: 'PATCH', body: JSON.stringify({ [key]: e.target.checked }) }), 'Module toggled.')} data-testid={`toggle-module-${key}`} /><span className="slider" /></label></div>)}</div></div>
  <div className="settings-card"><div className="settings-card-head"><div className="settings-card-title">Designations</div><div className="settings-card-desc">Manage employee job titles</div></div><div className="settings-card-body"><div className="tag-list">{data.designations.map((d) => <span key={d.id} className="tag"><span>{d.name}</span>{d.isSystem ? null : <><button className="row-action" onClick={() => { const name = window.prompt('Designation name', d.name); if (name?.trim()) void run(() => setupRequest('/setup/designations/' + d.id, { method: 'PATCH', body: JSON.stringify({ name: name.trim() }) }), 'Designation updated.'); }} data-testid={'button-edit-designation-' + d.id} aria-label={'Edit designation ' + d.name}><Pencil size={12} /></button><button className="row-action-delete" onClick={() => { if (window.confirm('Delete "' + d.name + '"?')) void run(() => setupRequest('/setup/designations/' + d.id, { method: 'DELETE' }), 'Designation deleted.'); }} data-testid={'button-delete-designation-' + d.id} aria-label={'Delete designation ' + d.name}><Trash2 size={12} /></button></>}</span>)}</div><div className="settings-add-row"><input className="field" value={designationName} onChange={(e) => setDesignationName(e.target.value)} onKeyDown={(e) => { if (e.key === 'Enter' && designationName.trim()) { void run(() => setupRequest('/setup/designations', { method: 'POST', body: JSON.stringify({ name: designationName.trim() }) }), 'Designation added.'); setDesignationName(''); } }} placeholder="New designation" data-testid="input-designation-name" /><button className="btn btn-quiet btn-sm" onClick={() => { if (!designationName.trim()) return; void run(() => setupRequest('/setup/designations', { method: 'POST', body: JSON.stringify({ name: designationName.trim() }) }), 'Designation added.'); setDesignationName(''); }} data-testid="button-add-designation"><Plus size={14} /></button></div></div></div>
</div></div>;
}

function Grades() {
  const qc = useQueryClient();
  const [grades, setGrades] = useState<{id: number; name: string; sections: {id: number; name: string}[]}[]>([]);
  const [loading, setLoading] = useState(true);
  const [gradeInput, setGradeInput] = useState('');
  const [sectionInputs, setSectionInputs] = useState<Record<number, string>>({});
  const [notice, setNotice] = useState('');
  const [error, setError] = useState('');
  const studentsQuery = useListStudents();
  const students = studentsQuery.data ?? [];
  const load = async () => { try { const d = await setupRequest('/setup/grades'); setGrades(d); setError(''); } catch (e) { setError(e instanceof Error ? e.message : 'Could not load grades'); } finally { setLoading(false); } };
  useEffect(() => { void load(); }, []);
  const run = async (action: () => Promise<unknown>, success: string) => { try { await action(); await load(); setNotice(success); setError(''); } catch (e) { setError(e instanceof Error ? e.message : 'Operation failed'); } };
  const addGrade = () => { if (!gradeInput.trim()) return; void run(() => setupRequest('/setup/grades', { method: 'POST', body: JSON.stringify({ name: gradeInput.trim() }) }), 'Grade created.'); setGradeInput(''); };
  const addSection = (gradeId: number) => { const name = sectionInputs[gradeId]?.trim(); if (!name) return; void run(() => setupRequest('/setup/grades/' + gradeId + '/sections', { method: 'POST', body: JSON.stringify({ name }) }), 'Section created.'); setSectionInputs({ ...sectionInputs, [gradeId]: '' }); };
  const editGrade = (grade: {id: number; name: string}) => { const name = window.prompt('Rename grade', grade.name); if (name?.trim()) void run(() => setupRequest('/setup/grades/' + grade.id, { method: 'PATCH', body: JSON.stringify({ name: name.trim() }) }), 'Grade updated.'); };
  const deleteGrade = (grade: {id: number; name: string}) => { if (window.confirm('Delete grade "' + grade.name + '" and all its sections?')) void run(() => setupRequest('/setup/grades/' + grade.id, { method: 'DELETE' }), 'Grade deleted.'); };
  const editSection = (section: {id: number; name: string}) => { const name = window.prompt('Rename section', section.name); if (name?.trim()) void run(() => setupRequest('/setup/sections/' + section.id, { method: 'PATCH', body: JSON.stringify({ name: name.trim() }) }), 'Section updated.'); };
  const deleteSection = (section: {id: number; name: string}) => { if (window.confirm('Delete section "' + section.name + '"?')) void run(() => setupRequest('/setup/sections/' + section.id, { method: 'DELETE' }), 'Section deleted.'); };
  const countStudents = (gradeId: number, sectionId?: number) => students.filter((s) => sectionId ? s.classId === gradeId && s.sectionId === sectionId : s.classId === gradeId).length;
  const totalSections = grades.reduce((sum, g) => sum + g.sections.length, 0);
  return <div className="content"><PageHead eyebrow="Academic structure" title="Grades &amp; Sections" subtitle="Organize your school into grades, each with its own sections." action={<span className="mono" data-testid="text-grade-count">{grades.length} grades, {totalSections} sections</span>} />{notice ? <div className="notice" data-testid="status-grades">{notice}</div> : null}{error ? <div className="notice" style={{ color: 'var(--rose)' }}>{error}</div> : null}<div className="grade-grid" data-testid="panel-grades">{loading ? <><div className="skeleton-card" /><div className="skeleton-card" /><div className="skeleton-card" /></> : <>{grades.map((grade) => <div className="grade-card" key={grade.id} data-testid={'row-grade-' + grade.id}><div className="grade-card-head"><div className="grade-card-name">{grade.name}</div><div className="grade-card-actions"><button className="row-action" onClick={() => editGrade(grade)} data-testid={'button-edit-grade-' + grade.id} aria-label={'Edit grade ' + grade.name}><Pencil size={13} /></button><button className="row-action-delete" onClick={() => deleteGrade(grade)} data-testid={'button-delete-grade-' + grade.id} aria-label={'Delete grade ' + grade.name}><Trash2 size={13} /></button></div></div><div className="grade-card-count">{countStudents(grade.id)} students</div><div className="grade-card-sections">{grade.sections.map((section) => <div className="grade-section" key={section.id} data-testid={'tag-section-' + section.id}><div className="grade-section-left"><span className="grade-section-name">Section {section.name}</span><span className="grade-section-count">{countStudents(grade.id, section.id)}</span></div><div className="grade-section-actions"><button className="row-action" onClick={() => editSection(section)} data-testid={'button-edit-section-' + section.id} aria-label={'Edit section ' + section.name}><Pencil size={11} /></button><button className="row-action-delete" onClick={() => deleteSection(section)} data-testid={'button-delete-section-' + section.id} aria-label={'Delete section ' + section.name}><Trash2 size={11} /></button></div></div>)}<div className="grade-add-section"><input className="field" value={sectionInputs[grade.id] ?? ''} onChange={(e) => setSectionInputs({ ...sectionInputs, [grade.id]: e.target.value })} onKeyDown={(e) => { if (e.key === 'Enter') addSection(grade.id); }} placeholder={'Add section'} data-testid={'input-section-' + grade.id} /><button className="btn btn-quiet btn-sm" onClick={() => addSection(grade.id)} data-testid={'button-add-section-' + grade.id}><Plus size={12} /></button></div></div></div>)}<div className="grade-card grade-card-add" data-testid="card-add-grade"><div className="grade-card-add-inner"><input className="field" value={gradeInput} onChange={(e) => setGradeInput(e.target.value)} onKeyDown={(e) => { if (e.key === 'Enter') addGrade(); }} placeholder="New grade name" data-testid="input-grade-name" /><button className="btn btn-primary btn-sm" onClick={addGrade} data-testid="button-add-grade"><Plus size={14} /> Add grade</button></div></div></>}</div></div>;
}
function Router() {
  const [location] = useLocation();
  return <ErrorBoundary resetKey={location}><Layout><Switch><Route path="/" component={Dashboard} /><Route path="/admissions" component={Admissions} /><Route path="/students" component={Students} /><Route path="/grades" component={Grades} /><Route path="/hr" component={HR} /><Route path="/finance" component={Finance} /><Route path="/settings" component={PersistentSettings} /><Route component={NotFound} /></Switch></Layout></ErrorBoundary>;
}

function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}

export default App;
